"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useAuth } from "@/hooks/useAuth"; // useAuthフックからauthオブジェクトを取得
import { createUserWithEmailAndPassword, updateProfile } from "firebase/auth"; // Firebase Auth SDKから登録関数をインポート

export default function RegisterPage() {
  const router = useRouter();
  // useAuthからauth, isAuthenticated, isLoadingを取得
  const { auth, isAuthenticated, isLoading } = useAuth();

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [passwordConfirmation, setPasswordConfirmation] = useState("");
  const [apiError, setApiError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  // -------------------------
  // 副作用: 認証済みならトップへリダイレクト
  // -------------------------
  useEffect(() => {
    // 認証が完了し、かつログイン済みであれば（匿名ユーザーを除く）、トップへリダイレクト
    if (!isLoading && isAuthenticated) {
      router.push("/");
    }
  }, [isLoading, isAuthenticated, router]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-900 text-white">
        <p>認証状態を確認中...</p>
      </div>
    );
  }

  if (isAuthenticated) return null; // リダイレクト済み

  // -------------------------
  // フォーム送信ハンドラ
  // -------------------------
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setApiError("");
    setIsSubmitting(true);

    if (!auth) {
      setApiError("認証サービスが利用できません。");
      setIsSubmitting(false);
      return;
    }

    if (!name || !email || !password || !passwordConfirmation) {
      setApiError("すべての項目を入力してください。");
      setIsSubmitting(false);
      return;
    }

    if (password !== passwordConfirmation) {
      setApiError("パスワードと確認用パスワードが一致しません。");
      setIsSubmitting(false);
      return;
    }

    try {
      // 1. Firebase Authでユーザーを作成
      const userCredential = await createUserWithEmailAndPassword(
        auth,
        email,
        password
      );

      // 2. ユーザー名を設定
      if (userCredential.user) {
        await updateProfile(userCredential.user, {
          displayName: name,
        });
        // userStateはonAuthStateChangedリスナーにより更新されます
      }

      // 成功後は、副作用（useEffect）によってトップページへリダイレクトされます
    } catch (error: any) {
      let errorMessage = "登録に失敗しました。再試行してください。";
      // Firebase Authのエラーコードに基づいてエラーメッセージを処理
      if (error.code) {
        switch (error.code) {
          case "auth/email-already-in-use":
            errorMessage = "このメールアドレスは既に使用されています。";
            break;
          case "auth/invalid-email":
            errorMessage = "メールアドレスの形式が正しくありません。";
            break;
          case "auth/weak-password":
            errorMessage = "パスワードは6文字以上で設定してください。";
            break;
          default:
            // ログインページの実装に合わせ、詳細なエラーメッセージを提示
            errorMessage = `登録に失敗しました: ${error.message}`;
        }
      }
      setApiError(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  // -------------------------
  // コンポーネントのレンダリング (ログインページのデザインを踏襲)
  // -------------------------
  return (
    <div className="w-full max-w-xl p-8 bg-white rounded-xl shadow-2xl mx-auto z-10 mt-10 mb-8">
      <h2 className="text-center text-3xl font-bold text-gray-800 mb-6 border-b pb-3">
        会員登録
      </h2>

      {/* エラーメッセージ表示エリア */}
      {apiError && (
        <div className="mb-4 p-3 bg-red-100 text-red-700 rounded text-sm font-medium">
          {apiError}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* 1. ユーザー名 */}
        <div>
          <label
            htmlFor="name"
            className="block text-sm font-medium text-gray-700 mb-1"
          >
            ユーザー名
          </label>
          <input
            id="name"
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-red-500 focus:border-red-500 transition duration-150"
            required
            disabled={isSubmitting}
          />
        </div>

        {/* 2. メールアドレス */}
        <div>
          <label
            htmlFor="email"
            className="block text-sm font-medium text-gray-700 mb-1"
          >
            メールアドレス
          </label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-red-500 focus:border-red-500 transition duration-150"
            required
            disabled={isSubmitting}
          />
        </div>

        {/* 3. パスワード */}
        <div>
          <label
            htmlFor="password"
            className="block text-sm font-medium text-gray-700 mb-1"
          >
            パスワード
          </label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-red-500 focus:border-red-500 transition duration-150"
            required
            disabled={isSubmitting}
          />
        </div>

        {/* 4. 確認用パスワード */}
        <div>
          <label
            htmlFor="password_confirmation"
            className="block text-sm font-medium text-gray-700 mb-1"
          >
            確認用パスワード
          </label>
          <input
            id="password_confirmation"
            type="password"
            value={passwordConfirmation}
            onChange={(e) => setPasswordConfirmation(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-red-500 focus:border-red-500 transition duration-150"
            required
            disabled={isSubmitting}
          />
        </div>

        {/* 登録ボタン */}
        <div className="pt-2">
          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full bg-red-600 text-white py-3 rounded-lg font-semibold text-lg hover:bg-red-700 transition duration-150 shadow-lg disabled:bg-gray-400 disabled:cursor-not-allowed"
          >
            {isSubmitting ? "登録中..." : "登録する"}
          </button>
        </div>
      </form>

      {/* ログインページへのリンク */}
      <div className="mt-6 text-center">
        <Link
          href="/login"
          className="text-sm text-blue-500 hover:text-blue-700 transition duration-150 font-medium"
        >
          ログインはこちら
        </Link>
      </div>
    </div>
  );
}
